insert into public.evidence_references(id,project_state_id,title,created_by) values ('00000000-0000-4000-8000-00000000f071','00000000-0000-4000-8000-00000000f020','Synthetic agreement','00000000-0000-4000-8000-00000000f001');
select set_config('test.contract_data',(current_setting('test.contract_data')::jsonb||'{"partyIds":["00000000-0000-4000-8000-00000000f070"],"agreementEvidenceId":"00000000-0000-4000-8000-00000000f071","riskAssessment":"none_identified"}')::text,true);
select set_config('test.setup_evidence',(select jsonb_agg(jsonb_build_object('requirement',k,'state','satisfied','details','Reviewed synthetic basis','evidenceReference','fixture:approved-record','accountableUserId','00000000-0000-4000-8000-00000000f001','materialBlocker',false,'roleAssignments',jsonb_build_object('project_lead','00000000-0000-4000-8000-00000000f001','coordination_document_control','00000000-0000-4000-8000-00000000f001','commercial_finance','00000000-0000-4000-8000-00000000f001','oversight','00000000-0000-4000-8000-00000000f001'),'fieldLeadership','not_applicable','fieldLeadershipReason','No field activity in this synthetic fixture'))::text from unnest(private.setup_requirement_keys()) k),true);
