select public.save_project_setup('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f049',(select jsonb_agg(case when e->>'requirement'='leadership' then jsonb_set(e,'{state}','"unresolved"') else e end) from jsonb_array_elements(current_setting('test.setup_evidence')::jsonb) e));
