select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f060');
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','missing_contract_review_permission','membership and preparation permission do not grant approval');
reset role;
insert into public.user_permission_overrides(workspace_id,user_id,permission_key,effect) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','project.contract.review','grant');
set local role authenticated;
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','contract_owner_authority_required','review permission is not owner authority');
