insert into public.workspace_business_owners(id,workspace_id,user_id,evidence_reference,effective_from) values ('00000000-0000-4000-8000-00000000f080','00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','Synthetic verified owner',now()+interval '1 day');
set local role authenticated;
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','contract_owner_authority_required','future owner record cannot approve');
reset role; update public.workspace_business_owners set effective_from=now()-interval '1 day'; set local role authenticated;
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','contract_strong_verification_required','AAL1 cannot approve despite owner identity');
select set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-00000000f001','role','authenticated','aal','aal2','session_id','00000000-0000-4000-8000-00000000f090','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',extract(epoch from now()))))::text,true);
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','contract_strong_verification_required','missing live session cannot approve');
reset role;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values ('00000000-0000-4000-8000-00000000f091','00000000-0000-4000-8000-00000000f001','totp','verified',now(),now());
insert into auth.sessions(id,user_id,aal,factor_id,created_at,updated_at) values ('00000000-0000-4000-8000-00000000f090','00000000-0000-4000-8000-00000000f001','aal2','00000000-0000-4000-8000-00000000f091',now(),now()); set local role authenticated;
select set_config('request.jwt.claims',(jsonb_build_object('sub','00000000-0000-4000-8000-00000000f001','role','authenticated','aal','aal2','session_id','00000000-0000-4000-8000-00000000f090','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',extract(epoch from now()-interval '6 minutes'))))::text)::jsonb::text,true);
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','held','Synthetic reviewed basis','{"agreementAuthorized":false,"commercialTermsReviewed":false,"effectivenessReviewed":false,"noMaterialBlockers":false}')$$,'P0001','contract_strong_verification_required','stale TOTP is not recent verification');
select set_config('request.jwt.claims',(jsonb_build_object('sub','00000000-0000-4000-8000-00000000f001','role','authenticated','aal','aal2','session_id','00000000-0000-4000-8000-00000000f090','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',extract(epoch from now()))))::text)::jsonb::text,true);
