select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','held','Synthetic reviewed basis','{"agreementAuthorized":false,"commercialTermsReviewed":false,"effectivenessReviewed":false,"noMaterialBlockers":false}')$$,'P0001','contract_strong_verification_required','factor must remain verified for a new decision');
reset role; update auth.mfa_factors set status='verified' where id='00000000-0000-4000-8000-00000000f091'; set local role authenticated;
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":false,"commercialTermsReviewed":false,"effectivenessReviewed":false,"noMaterialBlockers":false}')$$,'P0001','review_confirmations_required','approval checks start unconfirmed');
select is(public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','held','Synthetic reviewed basis','{"agreementAuthorized":false,"commercialTermsReviewed":false,"effectivenessReviewed":false,"noMaterialBlockers":false}')->>'status','held','owner can Hold without authorizing work');
select is(public.read_project_contract('00000000-0000-4000-8000-00000000f020')->>'approvalVerified','false','Hold never approves');
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000065','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','contract_review_sequence_conflict','concurrent stale decision rejected');
select is(public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,1,'00000000-0000-4000-8000-000000000065','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')->>'approvalVerified','true','confirmed owner with strong session approves exact current basis');
select is(public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,1,'00000000-0000-4000-8000-000000000065','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')->>'approvalVerified','true','lost response recovers same decision');
select is((select count(*)::integer from public.project_contract_review_decisions),2,'one Hold and one approval only');
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,1,'00000000-0000-4000-8000-000000000065','00000000-0000-4000-8000-00000000f080','rejected','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','request_id_payload_mismatch','cannot reuse request to change outcome');
select ok(not (public.read_project_setup('00000000-0000-4000-8000-00000000f020')->'unmet' ? 'contract_review'),'current approval satisfies canonical contract projection');
select ok(public.read_project_setup('00000000-0000-4000-8000-00000000f020')->'unmet' ? 'leadership','contract review does not satisfy other Setup conditions');
select is((select stage::text from public.project_states where id='00000000-0000-4000-8000-00000000f020'),'project_authorization_setup','contract approval does not advance the project');
savepoint positive_gate;
reset role;
insert into public.user_permission_overrides(workspace_id,user_id,permission_key,effect) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','project.gate01.decide','grant');
set local role authenticated;
select public.save_project_setup('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f048',(select jsonb_agg(case when e->>'requirement'='contract_review' then e||'{"details":"Forged checklist override"}'::jsonb else e end) from jsonb_array_elements(current_setting('test.setup_evidence')::jsonb) e));
select is((select e->>'details' from public.project_setup_versions s cross join lateral jsonb_array_elements(s.evidence) e where s.version=2 and e->>'requirement'='contract_review'),'Reviewed synthetic basis','Setup cannot overwrite the contract-owned alias');

select throws_ok($$select public.decide_project_gate01('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-00000000f047',null,'go','Separate gate review','[]')$$,'P0001','owner_authority_unresolved','contract owner does not grant separate gate authority');
reset role;
insert into public.project_gate01_authorities(id,workspace_id,user_id,basis,owner_approval_reference,effective_from) values ('00000000-0000-4000-8000-00000000f046','00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','confirmed_owner','Synthetic separate gate authority',now()-interval '1 day');
set local role authenticated;
select is((public.decide_project_gate01('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-00000000f047','00000000-0000-4000-8000-00000000f046','go','Separate gate review','[]')).disposition,'go','separate authority and complete Setup permit Gate 01');
select is((select stage::text from public.project_states where id='00000000-0000-4000-8000-00000000f020'),'preconstruction_mobilization','same Project State enters Mobilization');
select is((select evidence_snapshot->>'authorizationRecordId' from public.project_gate01_decisions limit 1),'00000000-0000-4000-8000-00000000f030','gate preserves frozen upstream identity');
-- pgTAP counter state is transactional: assertions in a rolled-back savepoint would disappear.
release savepoint positive_gate;
reset role;
-- Return this disposable fixture to Setup for subsequent denial tests only.
update public.project_states set stage='project_authorization_setup',commercial_stage='project_authorization_setup' where id='00000000-0000-4000-8000-00000000f020';
set local role authenticated;
reset role; select throws_ok($$update public.decisions set outcome='approved' where decision_type='contract_review'$$,'P0001','contract_decision_is_immutable','shared decision history cannot be rewritten');
insert into public.risk_issues(project_state_id,kind,title,severity,created_by) values ('00000000-0000-4000-8000-00000000f020','blocker','Synthetic unresolved contractual risk','high','00000000-0000-4000-8000-00000000f001'); set local role authenticated;
select is(public.read_project_contract('00000000-0000-4000-8000-00000000f020')->>'status','review_stale','new risk invalidates current readiness without rewriting approval');
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,2,'00000000-0000-4000-8000-000000000066','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','contract_risk_resolution_required','owner cannot silently waive material risk');
select throws_ok($$select public.decide_project_gate01('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f051',null,'go','Synthetic gate','[]')$$,'P0001','contract_authorized_review_required','stale contract approval cannot advance');
reset role; update public.workspace_business_owners set revoked_at=now(); set local role authenticated;
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,2,'00000000-0000-4000-8000-000000000066','00000000-0000-4000-8000-00000000f080','held','Synthetic reviewed basis','{"agreementAuthorized":false,"commercialTermsReviewed":false,"effectivenessReviewed":false,"noMaterialBlockers":false}')$$,'P0001','contract_owner_authority_required','revoked owner record cannot make new decisions');
reset role; update public.workspace_business_owners set revoked_at=null,effective_until=now()-interval '1 minute'; set local role authenticated;
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,2,'00000000-0000-4000-8000-000000000066','00000000-0000-4000-8000-00000000f080','held','Synthetic reviewed basis','{"agreementAuthorized":false,"commercialTermsReviewed":false,"effectivenessReviewed":false,"noMaterialBlockers":false}')$$,'P0001','contract_owner_authority_required','expired owner record cannot decide');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f002","role":"authenticated"}',true);
select is((select count(*)::integer from public.project_contract_review_decisions),0,'outsider cannot see contract decisions');
select throws_ok($$select public.decide_project_contract_review('00000000-0000-4000-8000-00000000f020',1,0,'00000000-0000-4000-8000-000000000064','00000000-0000-4000-8000-00000000f080','approved','Synthetic reviewed basis','{"agreementAuthorized":true,"commercialTermsReviewed":true,"effectivenessReviewed":true,"noMaterialBlockers":true}')$$,'P0001','project_state_not_found_or_access_denied','outsider decision rejected');
select * from finish();
rollback;
